/// <param name="cancellationToken">Cancels opening the reader.</param>
/// <returns>A task producing the opened reader.</returns>
internal async Task<DbDataReader> OpenRawReaderAsync<TResult>(IPreparedQueryCommand<TResult> preparedQueryCommand, object[]? @params, CancellationToken cancellationToken)
{
